    this.searchParamsSubject = new BehaviorSubject(this.searchData);
    this.filtersSubject = new BehaviorSubject(DEFAULT_FILTERS);
    this.configSubject = new BehaviorSubject(DEFAULT_SEARCH_RESULTS_CONFIG);
    // 🧹 CLEANUP
    this.destroy$ = new Subject();
    // 📅 COMPUTED PROPERTIES
    this.today = new Date().toISOString().split('T')[0];
    this.tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];
    // 🗺️ CONFIGURACIONES ESTÁTICAS
    this.northZones = Object.entries(ARMENIA_NORTH_ZONES).map(([key, value]) => ({
      key: key,
      name: value.name,
      description: value.description,
      icon: value.icon
    }));
    this.sortOptions = SORT_OPTIONS;
    this.itemsPerPageOptions = [5, 10, 20, 50];
    // 🔄 FILTROS ACTUALES (para UI)
    this.currentMinRating = 0;
    this.initializeObservables();
  }
  ngOnInit() {
    this.loadSearchParamsFromRoute();
    this.setupSearch();
  }
  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
  // ================================
  // 🔄 INICIALIZACIÓN
  // ================================
  initializeObservables() {
    this.searchParams$ = this.searchParamsSubject.asObservable();
    this.filters$ = this.filtersSubject.asObservable();
    this.config$ = this.configSubject.asObservable();
    // Combinar parámetros de búsqueda y filtros para obtener resultados
    this.filteredProperties$ = combineLatest([this.searchParams$, this.filters$, this.config$]).pipe(debounceTime(300), distinctUntilChanged(), switchMap(([searchParams, filters, config]) => this.propertyService.getProperties().pipe(map(properties => this.applyFiltersAndSort(properties, searchParams, filters, config)))));
  }
  loadSearchParamsFromRoute() {
    this.route.queryParams.pipe(takeUntil(this.destroy$)).subscribe(params => {
      const searchParams = {
        destination: params['zone'] || params['destination'] || '',
        checkIn: params['checkIn'] || '',
        checkOut: params['checkOut'] || '',
        guests: +params['guests'] || 2
      };
      this.searchData = {
        ...searchParams
      };
      this.searchParamsSubject.next(searchParams);
    });
  }
  setupSearch() {
    this.filteredProperties$.pipe(takeUntil(this.destroy$)).subscribe({
      next: properties => {
        this.totalResults = properties.length;
        this.isLoading = false;
      },
      error: error => {
        this.isLoading = false;
        this.searchError = 'Error buscando habitaciones. Inténtalo de nuevo.';
        console.error('❌ Error en búsqueda:', error);
      }
    });
  }
  // ================================
  // 🔍 APLICAR FILTROS Y ORDENAMIENTO
  // ================================
  applyFiltersAndSort(properties, searchParams, filters, config) {
    let filtered = [...properties];
    // Aplicar búsqueda por zona
    if (searchParams.destination) {
      filtered = filtered.filter(p => p.zone === searchParams.destination);
    }
    // Aplicar filtro de huéspedes
    if (searchParams.guests) {
      filtered = filtered.filter(p => p.maxGuests >= searchParams.guests);
    }
    // Aplicar filtros de zona
    if (filters.zones) {
      const activeZones = Object.entries(filters.zones).filter(([_, active]) => active).map(([zone, _]) => zone);
      if (activeZones.length > 0) {
        filtered = filtered.filter(p => activeZones.includes(p.zone));
      }
    }
    // Aplicar filtros de tipo de propiedad
    if (filters.propertyTypes) {
      const activeTypes = Object.entries(filters.propertyTypes).filter(([_, active]) => active).map(([type, _]) => type);
      if (activeTypes.length > 0) {
        filtered = filtered.filter(p => activeTypes.includes(p.propertyType));
      }
    }
    // Aplicar filtros de amenidades
    if (filters.amenities) {
      const activeAmenities = Object.entries(filters.amenities).filter(([_, active]) => active).map(([amenity, _]) => amenity);
      if (activeAmenities.length > 0) {
        filtered = filtered.filter(p => activeAmenities.every(amenity => p.amenities.includes(amenity)));
      }
    }
    // Aplicar filtros de servicios
    if (filters.services) {
      const activeServices = Object.entries(filters.services).filter(([_, active]) => active).map(([service, _]) => service);
      if (activeServices.length > 0) {
        filtered = filtered.filter(p => activeServices.every(service => p.services.includes(service)));
      }
    }
    // Aplicar filtros de precio
    if (filters.priceMin || filters.priceMax) {
      filtered = filtered.filter(p => p.pricePerNight >= (filters.priceMin || 0) && p.pricePerNight <= (filters.priceMax || Infinity));
    }
    // Aplicar filtro de calificación
    if (filters.minRating) {
      filtered = filtered.filter(p => p.rating >= filters.minRating);
    }
    // Aplicar filtros especiales
    if (filters.verified) {
      filtered = filtered.filter(p => p.isVerified);
    }
    if (filters.instantBook) {
      filtered = filtered.filter(p => p.isInstantBook);
    }
    // Aplicar ordenamiento
    return this.sortProperties(filtered, config.sortBy);
